INSERT INTO `sym_entries_data_18` (`id`, `entry_id`, `value`, `value_formatted`)
VALUES
	(8,907,'<p style=\"margin-left:0cm; margin-right:0cm\">Une mini-s&#233;rie de sept vid&#233;os a &#233;t&#233; r&#233;alis&#233;e pour recueillir le t&#233;moignage de passionn&#233;s du Mont Ventoux. Malgr&#233; leurs activit&#233;s vari&#233;es, ces hommes ont tous un point commun&#160;: l&#8217;amour pour la for&#234;t du Ventoux et le respect de ce milieu naturel pr&#233;serv&#233;.</p>\r\n\r\n<p style=\"margin-left:0cm; margin-right:0cm\">Les vid&#233;os sont disponibles <a href=\"http://www.ma-foret-mon-ventoux.smaemv.fr/\" target=\"_blank\">ici</a>.</p>\r\n','<p style=\"margin-left:0cm; margin-right:0cm\">Une mini-s&#233;rie de sept vid&#233;os a &#233;t&#233; r&#233;alis&#233;e pour recueillir le t&#233;moignage de passionn&#233;s du Mont Ventoux. Malgr&#233; leurs activit&#233;s vari&#233;es, ces hommes ont tous un point commun&#160;: l&#8217;amour pour la for&#234;t du Ventoux et le respect de ce milieu naturel pr&#233;serv&#233;.</p>\r\n\r\n<p style=\"margin-left:0cm; margin-right:0cm\">Les vid&#233;os sont disponibles <a href=\"http://www.ma-foret-mon-ventoux.smaemv.fr/\" target=\"_blank\">ici</a>.</p>\r\n');

/*!40000 ALTER TABLE `sym_entries_data_18` ENABLE KEYS */;
UNLOCK TABLES;


